method below_zero(operations: seq<int>) returns (result: bool)
    requires |operations| > 0 // The list of operations should not be empty
    ensures result == (exists i :: 0 <= i < |operations| && (sum(0, i + 1, operations) < 0))
{
    var balance := 0;
    result := false;
    var i := 0;

    while i < |operations|
        invariant 0 <= i <= |operations|
        invariant balance == sum(0, i, operations) // Balance is the sum of operations up to index i
    {
        balance := balance + operations[i];

        if balance < 0 {
            result := true;
            return;
        }

        i := i + 1;
    }

    result := false;
}
```

